{
  "title": "A slower day in Đà Lạt",
  "summary": "One unhurried nature stop, the must-do bánh căn lunch, and a long evening meal with room to wander.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "From what Tokek knows so far, the flower garden is the one activity that survives the slower pace, and it deserves a long, lazy look."
    },
    {
      "poi_id": "p22",
      "kind": "meal",
      "must_do_id": "m2",
      "note": "From what Tokek knows so far, the must-do bánh căn stays put for lunch, because a slower day still eats very well."
    },
    {
      "poi_id": "p123",
      "kind": "meal",
      "must_do_id": null,
      "note": "From what Tokek knows so far, dinner moves to the same side of town as lunch, so the evening stays short-ride simple."
    }
  ]
}
